#include "camera.hpp"
#include <opencv2/imgproc.hpp>
#include <iostream>
#include <memory>
#include <thread>
using namespace liquid;

Grid signedDistance(const cv::Mat& mask,float extent){Grid g(mask.cols,extent);int active=cv::countNonZero(mask);if(active==0){std::fill(g.data.begin(),g.data.end(),10.f);return g;}if(active==mask.rows*mask.cols){std::fill(g.data.begin(),g.data.end(),-10.f);return g;}cv::Mat inside,outside,inverted;cv::bitwise_not(mask,inverted);cv::distanceTransform(inverted,outside,cv::DIST_L2,cv::DIST_MASK_3);cv::distanceTransform(mask,inside,cv::DIST_L2,cv::DIST_MASK_3);float s=g.cell();for(int y=0;y<mask.rows;++y){const float* o=outside.ptr<float>(y);const float* in=inside.ptr<float>(y);float* dst=g.data.data()+y*mask.cols;for(int x=0;x<mask.cols;++x)dst[x]=(o[x]-in[x])*s;}return g;}
void filterBody(cv::Mat& mask,bool largest){cv::Mat labels,stats,centres;int count=cv::connectedComponentsWithStats(mask,labels,stats,centres,8,CV_32S);int best=-1,bestArea=29;std::vector<uint8_t> keep(count,0);for(int k=1;k<count;++k){int a=stats.at<int>(k,cv::CC_STAT_AREA);if(a>=30)keep[k]=255;if(a>bestArea){best=k;bestArea=a;}}if(largest){std::fill(keep.begin(),keep.end(),0);if(best>=0)keep[best]=255;}for(int y=0;y<mask.rows;++y){auto* row=mask.ptr<uint8_t>(y);auto* ids=labels.ptr<int>(y);for(int x=0;x<mask.cols;++x)row[x]=keep[ids[x]];}}

Camera::~Camera(){if(stream_.isValid()){stream_.stop();stream_.destroy();}if(device_.isValid())device_.close();if(initialized_)openni::OpenNI::shutdown();}
void Camera::open(const Options&o){if(openni::OpenNI::initialize()!=openni::STATUS_OK)throw std::runtime_error(openni::OpenNI::getExtendedError());initialized_=true;if(device_.open(openni::ANY_DEVICE)!=openni::STATUS_OK)throw std::runtime_error(std::string("OpenNI device: ")+openni::OpenNI::getExtendedError());if(stream_.create(device_,openni::SENSOR_DEPTH)!=openni::STATUS_OK)throw std::runtime_error("Cannot create depth stream");const auto* info=device_.getSensorInfo(openni::SENSOR_DEPTH);bool found=false;if(info){const auto&modes=info->getSupportedVideoModes();for(int i=0;i<modes.getSize();++i){const auto&m=modes[i];if(m.getResolutionX()==o.cameraWidth&&m.getResolutionY()==o.cameraHeight&&m.getFps()==o.cameraFPS&&m.getPixelFormat()==openni::PIXEL_FORMAT_DEPTH_1_MM){if(stream_.setVideoMode(m)==openni::STATUS_OK)found=true;break;}}}if(!found)throw std::runtime_error("Requested OpenNI DEPTH_1_MM mode unavailable");stream_.setMirroringEnabled(false);if(stream_.start()!=openni::STATUS_OK)throw std::runtime_error("Cannot start depth stream");}
bool Camera::read(cv::Mat&crop){openni::VideoStream* streams[]={&stream_};int ready=0;auto status=openni::OpenNI::waitForAnyStream(streams,1,&ready,100);if(status==openni::STATUS_TIME_OUT)return false;if(status!=openni::STATUS_OK)throw std::runtime_error("Depth wait failed");openni::VideoFrameRef frame;if(stream_.readFrame(&frame)!=openni::STATUS_OK||!frame.isValid())throw std::runtime_error("Depth read failed");if(frame.getVideoMode().getPixelFormat()!=openni::PIXEL_FORMAT_DEPTH_1_MM)throw std::runtime_error("Depth units are not millimetres");cv::Mat raw(frame.getHeight(),frame.getWidth(),CV_16UC1,const_cast<void*>(frame.getData()),size_t(frame.getStrideInBytes()));int side=std::min(raw.cols,raw.rows);cv::Rect roi((raw.cols-side)/2,(raw.rows-side)/2,side,side);if(side==120)crop=raw(roi).clone();else cv::resize(raw(roi),crop,{120,120},0,0,cv::INTER_NEAREST);return true;}

void captureLoop(const Options&o,std::atomic<bool>&run,Latest<CameraFrame>&shared,Counters&counters,std::string&error,std::mutex&errorMutex,volatile std::sig_atomic_t&interrupted){const cv::Mat kernel=cv::getStructuringElement(cv::MORPH_ELLIPSE,{3,3});auto began=Clock::now();auto nextDemo=began;uint64_t seq=0;while(run&&!interrupted){try{std::unique_ptr<Camera> camera;if(!o.demo){camera=std::make_unique<Camera>();camera->open(o);std::cerr<<"Astra connected.\n";}std::shared_ptr<CameraFrame> previous;int timeouts=0;while(run&&!interrupted){cv::Mat depth;Clock::time_point started;if(o.demo){std::this_thread::sleep_until(nextDemo);nextDemo+=std::chrono::microseconds(33333);started=Clock::now();depth=cv::Mat(120,120,CV_16UC1,cv::Scalar(3000));double t=seconds(began,started);int x=60+int(36*std::sin(t*.9));cv::ellipse(depth,{x,60},{9,24},25*std::sin(t*.7),0,360,cv::Scalar((o.minMM+o.maxMM)/2),-1);}else{if(!camera->read(depth)){if(++timeouts>=20)throw std::runtime_error("Astra timeout for ~2 seconds");continue;}timeouts=0;started=Clock::now();}auto f=std::make_shared<CameraFrame>();f->captured=started;f->seq=++seq;int validPixels=cv::countNonZero(depth);float validRatio=float(validPixels)/float(depth.rows*depth.cols);if(validRatio<.10f){f->valid=false;f->obstacle.sdf=Grid(120,o.sim.extent,10.f);if(o.gui){f->depth=depth;f->mask=cv::Mat::zeros(depth.size(),CV_8UC1);}f->ms=millis(started,Clock::now());counters.cameraMs=f->ms;++counters.cameraFrames;shared.set(f);previous.reset();continue;}cv::Mat mask;cv::inRange(depth,cv::Scalar(o.minMM),cv::Scalar(o.maxMM),mask);cv::morphologyEx(mask,mask,cv::MORPH_CLOSE,kernel);filterBody(mask,o.largestBody);f->valid=true;f->obstacle.sdf=signedDistance(mask,o.sim.extent);if(previous&&previous->valid){f->obstacle.previous=previous->obstacle.sdf;f->obstacle.frameDt=float(seconds(previous->captured,f->captured));f->obstacle.hasPrevious=f->obstacle.frameDt>0&&f->obstacle.frameDt<.2f;}if(o.gui){f->depth=depth;f->mask=mask;}f->ms=millis(started,Clock::now());counters.cameraMs=f->ms;++counters.cameraFrames;shared.set(f);previous=std::move(f);}return;}catch(const std::exception&e){if(!run||interrupted)break;if(o.demo){std::lock_guard<std::mutex> lock(errorMutex);error=e.what();run=false;break;}std::cerr<<"WARNING: Astra error: "<<e.what()<<"\nReconnecting Astra in 500ms...\n";std::this_thread::sleep_for(std::chrono::milliseconds(500));}}}
